using NUnit.Framework;

public class OneShotReleaseRuleTests
{
    // Generated by FMOD/Tools/instruments.py: kill chords keep their event's release, pattern layers end with the
    // timeline's region-end ramp (PATTERN_STOP_FADE_MS = 5; Docs/Captures/README.md Task 11).
    const double PatternStopFade = 0.005;

    [Test]
    public void KillChords_KeepTheirInstrumentRelease()
    {
        Assert.AreEqual(0.12, InstrumentTable.ReleaseSeconds(Instrument.Bells, OutputBus.KillChords), 1e-9);
    }

    [Test]
    public void PatternNotes_EndLikeTheTimeline_ShortStopFade()
    {
        Assert.AreEqual(PatternStopFade, InstrumentTable.ReleaseSeconds(Instrument.Bells, OutputBus.Harmony), 1e-9);
        Assert.AreEqual(PatternStopFade, InstrumentTable.ReleaseSeconds(Instrument.GlassPad, OutputBus.ComboPad), 1e-9);
        Assert.AreEqual(PatternStopFade, InstrumentTable.ReleaseSeconds(Instrument.ClavHigh, OutputBus.FunkKeys), 1e-9);
        Assert.AreEqual(PatternStopFade, InstrumentTable.ReleaseSeconds(Instrument.Bass, OutputBus.Bass), 1e-9);
    }
}
